import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, smoothstep, float, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight, Texture, DoubleSide } = THREE;

  const palette = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Journal', typography: { fontSize: 39 } };

  const group = new Group();
  group.name = 'journal-card-2-label';

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // Rounded-rect SDF mask (shared math) for label plate face + edge
  // ---------------------------------------------------------------
  const p = uv().sub(vec2(0.5, 0.5));
  const boxHalf = vec2(0.46, 0.4);
  const cornerR = float(0.08);
  const q = p.abs().sub(boxHalf).add(vec2(cornerR, cornerR));
  const outside = q.max(vec2(0.0, 0.0)).length();
  const insideMax = q.x.max(q.y);
  const inside = insideMax.min(float(0.0));
  const dist = outside.add(inside).sub(cornerR);

  const faceMask = float(1.0).sub(smoothstep(float(-0.015), float(0.015), dist));
  const edgeBand = float(1.0).sub(smoothstep(float(0.0), float(0.03), dist.abs()));

  // ---------------------------------------------------------------
  // Plate body (machined metal, extruded)
  // ---------------------------------------------------------------
  const plateGeo = new BoxGeometry(1.9, 0.6, 0.08);
  const plateMat = new MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  plateMat.colorNode = mix(color(palette.ink), color(palette.paper), float(0.05));
  const plate = new Mesh(plateGeo, plateMat);
  group.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---------------------------------------------------------------
  // Front textured face (rounded, masked, tinted for text contrast)
  // ---------------------------------------------------------------
  const placeholderTex = new Texture();
  const mapNode = texture(placeholderTex);

  const faceGeo = new PlaneGeometry(1.9, 0.6);
  const faceMat = new MeshStandardNodeMaterial({
    transparent: true,
    metalness: 0.15,
    roughness: 0.6,
    side: DoubleSide,
  });
  faceMat.colorNode = mix(mapNode.rgb, color(palette.ink), float(0.4));
  faceMat.opacityNode = faceMask;
  const face = new Mesh(faceGeo, faceMat);
  face.position.z = 0.045;
  group.add(face);
  disposables.push(faceGeo, faceMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mapNode.value = tex;
    });
  }

  // ---------------------------------------------------------------
  // Accent edge stroke (focus / hover indicator)
  // ---------------------------------------------------------------
  const accentIntensity = uniform(0.15);
  const edgeGeo = new PlaneGeometry(1.9, 0.6);
  const edgeMat = new MeshStandardNodeMaterial({
    transparent: true,
    metalness: 0.3,
    roughness: 0.4,
  });
  edgeMat.colorNode = color(palette.accent);
  edgeMat.emissiveNode = color(palette.accent).mul(accentIntensity);
  edgeMat.opacityNode = edgeBand.mul(accentIntensity.add(0.35));
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = 0.041;
  group.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // ---------------------------------------------------------------
  // Soft drop shadow behind plate (depth grounding cue)
  // ---------------------------------------------------------------
  const shadowUv = uv().sub(vec2(0.5, 0.5)).length();
  const shadowMask = float(1.0).sub(smoothstep(float(0.15), float(0.5), shadowUv));
  const shadowGeo = new PlaneGeometry(2.6, 1.0);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = shadowMask.mul(float(0.45));
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0.05, -0.12, -0.08);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // Local rim light (accent hue, node-local, <=1.5 intensity)
  // ---------------------------------------------------------------
  const rimLight = new PointLight(palette.accent, 0.7, 4.0);
  rimLight.position.set(-0.6, -0.3, -0.5);
  group.add(rimLight);

  // ---------------------------------------------------------------
  // Text: "Journal 2" headline label
  // ---------------------------------------------------------------
  const fontSize = headline.typography?.fontSize ?? 39;
  const textMesh = ctx.fontAtlas.createText(headline.text ?? 'Journal 2', {
    fontSize,
    color: palette.paper,
    align: 'center',
  });
  textMesh.position.set(0, 0, 0.06);
  group.add(textMesh);

  // ---------------------------------------------------------------
  // Cinematic primitive: parallax-scroll
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  const primitivesSpec = config.cinematicPrimitives ?? [];
  for (const prim of primitivesSpec) {
    if (ctx.primitives?.[prim.name]) {
      const handle = ctx.primitives[prim.name](group, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // Motion: hover rise-in + press-down + focus accent
  // ---------------------------------------------------------------
  const baseY = group.position.y;

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(group.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(accentIntensity, { value: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
  timelines.push(hoverTl);

  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(group.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
  timelines.push(settleTl);

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  timelines.push(pressTl);

  // gentle entrance
  const entranceTl = gsap.timeline();
  entranceTl.fromTo(
    group.position,
    { y: baseY - 0.2 },
    { y: baseY, duration: 0.7, ease: 'power3.out' }
  );
  entranceTl.fromTo(group.scale, { x: 0.98, y: 0.98, z: 0.98 }, { x: 1.0, y: 1.0, z: 1.0, duration: 0.6, ease: 'power2.out' }, 0);
  timelines.push(entranceTl);

  group.userData.handlers = {
    onPointerEnter: () => {
      hoverTl.play();
    },
    onPointerLeave: () => {
      hoverTl.reverse();
    },
    onFocus: () => {
      gsap.to(accentIntensity, { value: 1.0, duration: 0.3, ease: 'power2.out' });
    },
    onBlur: () => {
      gsap.to(accentIntensity, { value: 0.15, duration: 0.3, ease: 'power2.out' });
    },
    onPointerDown: () => {
      pressTl.play(0);
    },
    onPointerUp: () => {
      pressTl.reverse();
      settleTl.restart();
    },
    onClick: () => {
      ctx.emit('hub-journal.select', { nodeId: 'hub-journal-card-0-label', text: headline.text ?? 'Journal 2' });
    },
  };

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  group.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    for (const res of disposables) {
      res?.dispose?.();
    }
    if (mapNode.value && mapNode.value !== placeholderTex) {
      mapNode.value.dispose?.();
    }
    placeholderTex.dispose?.();

    textMesh?.traverse?.((child) => {
      child.geometry?.dispose?.();
      if (Array.isArray(child.material)) {
        child.material.forEach((m) => m.dispose?.());
      } else {
        child.material?.dispose?.();
      }
    });

    rimLight.dispose?.();
  };

  return group;
}
